class Router:
    """Maps URL paths to handlers.

    Routes are registered with `add`, and `resolve` returns (handler, params)
    for a path or (None, {}) when nothing matches.
    """

    def __init__(self):
        self._routes = []

    def add(self, path, handler):
        segments = path.split('/')
        is_static = True
        for seg in segments:
            if seg.startswith('<') and seg.endswith('>'):
                is_static = False
                break
        self._routes.append({
            'path': path,
            'handler': handler,
            'segments': segments,
            'is_static': is_static,
        })

    def resolve(self, path):
        path_segments = path.split('/')
        best_static = None
        best_dynamic = None
        for route in self._routes:
            segs = route['segments']
            if len(segs) != len(path_segments):
                continue
            params = {}
            matched = True
            for rs, ps in zip(segs, path_segments):
                if rs.startswith('<') and rs.endswith('>'):
                    if ps == '':
                        matched = False
                        break
                    name = rs[1:-1]
                    params[name] = ps
                else:
                    if rs != ps:
                        matched = False
                        break
            if not matched:
                continue
            if route['is_static']:
                if best_static is None:
                    best_static = (route['handler'], {})
            else:
                if best_dynamic is None:
                    best_dynamic = (route['handler'], params)
        if best_static is not None:
            return best_static[0], best_static[1]
        if best_dynamic is not None:
            return best_dynamic[0], best_dynamic[1]
        return None, {}

