class Router:
    """Maps URL paths to handlers.

    Routes are registered with `add`, and `resolve` returns (handler, params)
    for a path or (None, {}) when nothing matches.
    """

    def __init__(self):
        self._routes = []

    def add(self, path, handler):
        segs = path.split('/')
        is_static = True
        for seg in segs:
            if seg.startswith('<') and seg.endswith('>'):
                is_static = False
                break
        self._routes.append({
            'path': path,
            'handler': handler,
            'segs': segs,
            'is_static': is_static,
        })

    def resolve(self, path):
        req_segs = path.split('/')
        # First pass: static routes win over dynamic regardless of registration order
        for entry in self._routes:
            if entry['is_static'] and len(entry['segs']) == len(req_segs):
                if entry['segs'] == req_segs:
                    return entry['handler'], {}
        # Second pass: dynamic routes
        for entry in self._routes:
            if entry['is_static']:
                continue
            if len(entry['segs']) != len(req_segs):
                continue
            params = {}
            match = True
            for r_seg, req_seg in zip(entry['segs'], req_segs):
                if r_seg.startswith('<') and r_seg.endswith('>'):
                    # Parameter segment must not be empty
                    if not req_seg:
                        match = False
                        break
                    param_name = r_seg[1:-1]
                    params[param_name] = req_seg
                else:
                    if r_seg != req_seg:
                        match = False
                        break
            if match:
                return entry['handler'], params
        return None, {}

