class Router:
    """Maps URL paths to handlers.

    Routes are registered with `add`, and `resolve` returns (handler, params)
    for a path or (None, {}) when nothing matches.
    """

    def __init__(self):
        self._routes = []

    def add(self, path, handler):
        is_static = '<' not in path
        self._routes.append({'path': path, 'handler': handler, 'is_static': is_static})

    def resolve(self, path):
        # Static routes win over dynamic routes regardless of registration order
        for r in self._routes:
            if r['is_static']:
                if r['path'] == path:
                    return r['handler'], {}
        # Dynamic routes
        path_segs = path.split('/')
        for r in self._routes:
            if not r['is_static']:
                if self._match_dynamic(r['path'], path_segs):
                    params = self._extract_params(r['path'], path_segs)
                    return r['handler'], params
        return None, {}

    def _match_dynamic(self, route_path, path_segs):
        route_segs = route_path.split('/')
        if len(route_segs) != len(path_segs):
            return False
        for rs, ps in zip(route_segs, path_segs):
            if rs.startswith('<') and rs.endswith('>'):
                # parameter segment must be non-empty
                if ps == '':
                    return False
                continue
            if rs != ps:
                return False
        return True

    def _extract_params(self, route_path, path_segs):
        params = {}
        route_segs = route_path.split('/')
        for rs, ps in zip(route_segs, path_segs):
            if rs.startswith('<') and rs.endswith('>'):
                name = rs[1:-1]
                params[name] = ps
        return params
